import fs from 'fs';
import { env } from '../config/env';
import { paths } from '../config/paths';
import { Logger } from './Logger';

interface ManifestCache {
    modifiedAt: number;
    entries: Record<string, string>;
}

/** Resolves the versioned asset paths generated by laravel-mix (public/mix-manifest.json) */
export class AssetManifest {
    private static cache: ManifestCache | null = null;

    static url(fileName: string): string {
        const versionedPath = AssetManifest.entries()[fileName] ?? fileName;
        return env.appUrl + versionedPath;
    }

    /** The manifest is re-read only when the file changed (e.g. during `npm run watch`) */
    private static entries(): Record<string, string> {
        try {
            const modifiedAt = fs.statSync(paths.mixManifest).mtimeMs;

            if (AssetManifest.cache?.modifiedAt !== modifiedAt) {
                const entries = JSON.parse(fs.readFileSync(paths.mixManifest, 'utf8')) as Record<string, string>;
                AssetManifest.cache = { modifiedAt, entries };
            }

            return AssetManifest.cache.entries;
        }
        catch (error) {
            void Logger.error(`Error reading the asset path from mix-manifest.json: ${(error as Error).message}`);
            return {};
        }
    }
}
